Body:
I spent some time trying to filter out models I don’t use. The solution that worked for me was setting the disabled_providers parameter, even for a provider I actively use (LM Studio), in order to disable the three default providers. I hope this works for you as well.

```
{
  "$schema": "https://opencode.ai/config.json",
  "disabled_providers": ["openai", "opencode", "lmstudio"],
  "provider": {
    "localLMStudio": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "LM Studio",
      "options": {
        "baseURL": "http://127.0.0.1:1234/v1"
      },
      "models": {
        "qwen": {
          "name": "lmstudio/qwen2.5-coder-7b-instruct"
        }
      }
    }
  },
  "model": "localLMStudio/qwen"
}
```

